<script setup lang="ts">
definePageMeta({ middleware: 'auth' }); useSeoMeta({ title: '岗位详情' }); const route=useRoute(); const jobs=useJobsApi(); const data=ref<any>(); const loading=ref(true); const id=computed(()=>String(route.query.id||route.query.job_id||'')); onMounted(async()=>{if(id.value)data.value=await jobs.detail(id.value);loading.value=false})
</script>
